import{_ as t,o,c as r,j as a}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"0. 前言","description":"","frontmatter":{"abstract":"","date":"2021/09/25","date_time":"2021/09/25 21:03:17","file_name":"Java17-Updates-00-foreword","group":"Java17-Updates","keywords":"Java Java17","position":91,"tags":"Java|Java17 ","title":"0. 前言"},"headers":[],"relativePath":"topics/Java17-Updates/00-foreword.md","filePath":"topics/Java17-Updates/00-foreword.md","lastUpdated":1785284603000}'),s={name:"topics/Java17-Updates/00-foreword.md"};function d(p,e,l,n,v,J){return o(),r("div",null,[...e[0]||(e[0]=[a("p",null,"2021 年 9月 23 日，Java 17 发布了。",-1),a("p",null,"作为一门历史悠久的语言，随着更新频率的提升，Java 在最近几年又逐渐焕发出活力 —— 这当然并不是 Java 做得足够好，而是大环境如此。隔壁 C++ 在经历了十几年才发布 C++ 11 之后，标准更新的频率也明显得到了提升，例如 C++ 14、C++ 17，还有 C++ 20。有意思的是，C++ 比 Java 更早地将协程纳入语言标准，尽管用起来比较费事儿，但总比不断跳票的 Loom 要更实在一些。",-1),a("p",null,"对于 Java 新特性的期待，除了前面提到的 Loom 项目当中所带来的对协程的支持以外，还有 Valhalla 项目当中对于值类型的支持。遗憾的是，这二者都没有出现在 Java 17 的更新当中。不过，Java 17 也带来不少有用的内容，例如更安全的外部函数访问 API，转正的密封类等等。",-1),a("p",null,"当然，Java 的更新有时候也是看着热闹，真正能够用起来还是需要一些时间的。毕竟想要体验这些新特性，我们还需要升级 JDK 版本。不过，这并不影响我们尽早了解 Java 版本更新的内容。接下来，我们会用一系列文章来详细介绍 Java 17 的更新内容，希望能够为大家做个参考。",-1)])])}const f=t(s,[["render",d]]);export{c as __pageData,f as default};
